import{_ as a,c as s,o as i,aj as d}from"./chunks/framework.Id7s26SP.js";const k=JSON.parse('{"title":"Interface: Db3IndexesAPI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/js-bao-wss-client/api/interfaces/Db3IndexesAPI.md","filePath":"reference/js-bao-wss-client/api/interfaces/Db3IndexesAPI.md"}'),t={name:"reference/js-bao-wss-client/api/interfaces/Db3IndexesAPI.md"};function n(o,e,r,h,l,c){return i(),s("div",null,[...e[0]||(e[0]=[d('<p><a href="./../README.html"><strong>js-bao-wss-client</strong></a></p><hr><p><a href="./../globals.html">js-bao-wss-client</a> / Db3IndexesAPI</p><h1 id="interface-db3indexesapi" tabindex="-1">Interface: Db3IndexesAPI <a class="header-anchor" href="#interface-db3indexesapi" aria-label="Permalink to “Interface: Db3IndexesAPI”">​</a></h1><p>A db3&#39;s indexes, as <code>client.db3.indexes</code>. A declared <code>indexed</code> or <code>unique</code> field has its index already; register one for a field you query without declaring it, or for a composite unique key.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> index</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">register</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id, { model: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, field: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;email&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> });</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> all</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">list</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id);</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">drop</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id, index.name);</span></span></code></pre></div><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="accept" tabindex="-1">accept() <a class="header-anchor" href="#accept" aria-label="Permalink to “accept()”">​</a></h3><blockquote><p><strong>accept</strong>(<code>db3Id</code>, <code>name</code>): <code>Promise</code>&lt;<a href="./Db3LocalIndex.html"><code>Db3LocalIndex</code></a>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Build an index on this device again: one declined, one the client&#39;s <code>deviceIndexes</code> option leaves out, or one whose build failed. It is built before this resolves, from the copy&#39;s rows; when the build fails again the answer is <code>unbuilt</code> with why, and every later sync retries. An index already built answers <code>built</code> and is not rebuilt. Nothing is sent. Refused as <code>decline</code> is.</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id" tabindex="-1">db3Id <a class="header-anchor" href="#db3id" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The index&#39;s name, as <code>local</code> lists it.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3LocalIndex.html"><code>Db3LocalIndex</code></a>&gt;</p><p>The index&#39;s status here.</p><hr><h3 id="decline" tabindex="-1">decline() <a class="header-anchor" href="#decline" aria-label="Permalink to “decline()”">​</a></h3><blockquote><p><strong>decline</strong>(<code>db3Id</code>, <code>name</code>): <code>Promise</code>&lt;<a href="./Db3LocalIndex.html"><code>Db3LocalIndex</code></a>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Stop building an index on this device: its local table or index is dropped before this resolves, and it stays unbuilt across restarts, index-list refreshes, a drop and re-registration of the same index and an evict, until <code>accept</code> (or <code>client.db3.delete</code>). The room&#39;s index list is not changed, and other devices and the server keep the index. On this device a <code>$search</code> that needs a declined text index is refused <code>DB3_INDEX_DECLINED_ON_DEVICE</code>; a query a declined scalar or member index only speeds answers by a scan. Nothing is sent. Refused <code>DB3_INDEX_NOT_FOUND</code> for a name the db3 places on no device, and <code>DB3_LOCAL_ONLY</code> on a db3 that lives only on this device (drop its index instead).</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-1" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-1" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The index&#39;s name, as <code>local</code> lists it.</p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3LocalIndex.html"><code>Db3LocalIndex</code></a>&gt;</p><p>The index&#39;s status here: <code>declined</code>.</p><h4 id="example-1" tabindex="-1">Example <a class="header-anchor" href="#example-1" aria-label="Permalink to “Example”">​</a></h4><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">decline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;idx_text_note&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><hr><h3 id="deletemodel" tabindex="-1">deleteModel() <a class="header-anchor" href="#deletemodel" aria-label="Permalink to “deleteModel()”">​</a></h3><blockquote><p><strong>deleteModel</strong>(<code>db3Id</code>, <code>name</code>): <code>Promise</code>&lt;{ <code>name</code>: <code>string</code>; <code>ok</code>: <code>boolean</code>; <code>revision</code>: <code>number</code>; }&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Delete an <code>ann</code> vector index&#39;s shared model, or a device&#39;s upload under way, so a device trains it again: every device drops its copy and answers <code>$near</code> exactly until a new model is installed, and an upload naming the old revision is refused. Needs the db3&#39;s owner (or an app owner or admin). Refused <code>DB3_INDEX_MODEL_NOT_FOUND</code> when there is neither.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-2" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-2" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="name-2" tabindex="-1">name <a class="header-anchor" href="#name-2" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The vector index&#39;s name, as <code>list</code> answers it.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;{ <code>name</code>: <code>string</code>; <code>ok</code>: <code>boolean</code>; <code>revision</code>: <code>number</code>; }&gt;</p><p>The index&#39;s new <code>revision</code>.</p><hr><h3 id="drop" tabindex="-1">drop() <a class="header-anchor" href="#drop" aria-label="Permalink to “drop()”">​</a></h3><blockquote><p><strong>drop</strong>(<code>db3Id</code>, <code>name</code>): <code>Promise</code>&lt;<a href="./Db3DroppedIndex.html"><code>Db3DroppedIndex</code></a>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Remove your registration of an index. The index is dropped when no origin keeps it; one a declaration still keeps is refused with <code>DB3_INDEX_IN_USE</code>, naming the origins in <code>body.details.origins</code>. Waits first for a pending create of the db3 to commit: rejects <code>PENDING_CREATE</code> offline or after 30 s, or with the create&#39;s refusal (see <a href="./Db3API.html">Db3API</a>). On a db3 this client has open, its local copy no longer has the index when <code>drop</code> resolves, as <code>register</code> says. On a db3 that lives only on this device the drop is made there, a dropped unique index stops being enforced, and nothing is sent. Resolves the index&#39;s name and <code>cost</code>, the rows the server wrote and read to drop it (none on a db3 that lives only on this device).</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-3" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-3" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="name-3" tabindex="-1">name <a class="header-anchor" href="#name-3" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The index&#39;s name, as <code>list</code> answers it.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3DroppedIndex.html"><code>Db3DroppedIndex</code></a>&gt;</p><hr><h3 id="fetchmodel" tabindex="-1">fetchModel() <a class="header-anchor" href="#fetchmodel" aria-label="Permalink to “fetchModel()”">​</a></h3><blockquote><p><strong>fetchModel</strong>(<code>db3Id</code>, <code>name</code>): <code>Promise</code>&lt;<a href="./Db3IndexModel.html"><code>Db3IndexModel</code></a>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>An <code>ann</code> vector index&#39;s shared model: the bytes one device trained and uploaded, with its generation, revision, row count, training time and format. Devices holding the db3 fetch and install it themselves; this reads it for an app that keeps or inspects it. Needs read access. Refused <code>DB3_INDEX_MODEL_NOT_FOUND</code> while there is none.</p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-4" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-4" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="name-4" tabindex="-1">name <a class="header-anchor" href="#name-4" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The vector index&#39;s name, as <code>list</code> answers it.</p><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3IndexModel.html"><code>Db3IndexModel</code></a>&gt;</p><h4 id="example-2" tabindex="-1">Example <a class="header-anchor" href="#example-2" aria-label="Permalink to “Example”">​</a></h4><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> model</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">fetchModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;idx_vec_note_embedding&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(model.revision, model.rows, model.bytes.byteLength);</span></span></code></pre></div><hr><h3 id="list" tabindex="-1">list() <a class="header-anchor" href="#list" aria-label="Permalink to “list()”">​</a></h3><blockquote><p><strong>list</strong>(<code>db3Id</code>, <code>options?</code>): <code>Promise</code>&lt;<a href="./Db3Index.html"><code>Db3Index</code></a>[]&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Every index on the db3&#39;s records, sorted by name. Needs read access. On a db3 that lives only on this device the list is the device&#39;s own, under the same names and origins, and nothing is sent. Waits first for a pending create of the db3 to commit: rejects <code>PENDING_CREATE</code> offline or after 30 s, or with the create&#39;s refusal (see <a href="./Db3API.html">Db3API</a>).</p><h4 id="parameters-5" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-5" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-5" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-5" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="options" tabindex="-1">options? <a class="header-anchor" href="#options" aria-label="Permalink to “options?”">​</a></h5><p><a href="./RequestOptions.html"><code>RequestOptions</code></a></p><p>Per-request options (a <code>timeoutMs</code>, for one).</p><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3Index.html"><code>Db3Index</code></a>[]&gt;</p><hr><h3 id="local" tabindex="-1">local() <a class="header-anchor" href="#local" aria-label="Permalink to “local()”">​</a></h3><blockquote><p><strong>local</strong>(<code>db3Id</code>): <code>Promise</code>&lt;<a href="./Db3LocalIndex.html"><code>Db3LocalIndex</code></a>[]&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>The indexes the db3&#39;s room places on this device, sorted by name, each with how it stands here: <code>built</code>, <code>unbuilt</code> (with why) or <code>declined</code>. An index placed on the server only is left out. Read from this device&#39;s copy, so nothing is sent; the copy must be bound here (subscribe to it first). On a db3 that lives only on this device every index is listed, never <code>declined</code>.</p><h4 id="parameters-6" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-6" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-6" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-6" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h4 id="returns-6" tabindex="-1">Returns <a class="header-anchor" href="#returns-6" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3LocalIndex.html"><code>Db3LocalIndex</code></a>[]&gt;</p><h4 id="example-3" tabindex="-1">Example <a class="header-anchor" href="#example-3" aria-label="Permalink to “Example”">​</a></h4><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> index</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> of</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">local</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id)) {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (index.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!==</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;built&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">} (${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reason</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">})`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h3 id="register" tabindex="-1">register() <a class="header-anchor" href="#register" aria-label="Permalink to “register()”">​</a></h3><blockquote><p><strong>register</strong>(<code>db3Id</code>, <code>registration</code>): <code>Promise</code>&lt;<a href="./Db3Index.html"><code>Db3Index</code></a> &amp; <code>object</code>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Register an index and return it as it now is. Registering an index a declaration already keeps adds your origin to it. Needs the db3&#39;s owner, or an app owner or admin. Refused with <code>DB3_INDEX_NOT_UNIQUE</code> (and the shared values in <code>body.details.duplicates</code>) when <code>unique</code> meets records sharing a key. On a db3 that lives only on this device the index is registered and built on the device by the same rules (a refusal is a <code>JsBaoError</code> with the same code and <code>details</code>), a unique one is enforced there, and nothing is sent. Waits first for a pending create of the db3 to commit: rejects <code>PENDING_CREATE</code> offline or after 30 s, or with the create&#39;s refusal (see <a href="./Db3API.html">Db3API</a>).</p><p>On a db3 this client has open (subscribed), its local copy has the index when <code>register</code> resolves: a query on the field uses it at once. When the copy could not read the index list back, <code>register</code> still resolves (the index is registered), one warning says so, and the copy gets the index as soon as the list can be read. A copy kept on the device but not open gets it at its next subscribe, before <code>ready</code>.</p><p>With <code>members: true</code> on a string-set field, the db3 builds the field&#39;s member index from its records in this one request and keeps it on every write: <code>$contains</code>, any-of, membership levels and unfiltered facets on the field read it. A synced db3&#39;s copy on the device builds nothing for it; a db3 that lives only on this device builds it on the device and keeps it there. Refused with <code>DB3_INDEX_NOT_SET_FIELD</code> on a field that holds a single value.</p><p>The index resolves with <code>cost</code> beside its fields: the rows the server wrote and read to register it, its build and statistics included. A db3 that lives only on this device answers none.</p><h4 id="parameters-7" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-7" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-7" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-7" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="registration" tabindex="-1">registration <a class="header-anchor" href="#registration" aria-label="Permalink to “registration”">​</a></h5><p><a href="./../type-aliases/Db3IndexRegistration.html"><code>Db3IndexRegistration</code></a></p><p>The model and its field or fields.</p><h4 id="returns-7" tabindex="-1">Returns <a class="header-anchor" href="#returns-7" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3Index.html"><code>Db3Index</code></a> &amp; <code>object</code>&gt;</p><hr><h3 id="skipped" tabindex="-1">skipped() <a class="header-anchor" href="#skipped" aria-label="Permalink to “skipped()”">​</a></h3><blockquote><p><strong>skipped</strong>(<code>db3Id</code>): <code>Promise</code>&lt;<a href="./Db3SkippedIndex.html"><code>Db3SkippedIndex</code></a>[]&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>The entries of the db3&#39;s index list this device built nothing for, sorted by name, each with why: an index placed on the server only, and one the device cannot build (a name that is not an identifier, an index on <code>id</code>, which the primary key serves, a member or vector index over more than one field, text options it cannot read). <code>local</code> lists none of them. Read from this device&#39;s copy, so nothing is sent and it answers offline; the copy must be bound here (subscribe to it first).</p><h4 id="parameters-8" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-8" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-8" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-8" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h4 id="returns-8" tabindex="-1">Returns <a class="header-anchor" href="#returns-8" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3SkippedIndex.html"><code>Db3SkippedIndex</code></a>[]&gt;</p><h4 id="example-4" tabindex="-1">Example <a class="header-anchor" href="#example-4" aria-label="Permalink to “Example”">​</a></h4><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> index</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> of</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> client.db3.indexes.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">skipped</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(db3Id)) {</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">} on ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}: ${</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">reason</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h3 id="uploadmodel" tabindex="-1">uploadModel() <a class="header-anchor" href="#uploadmodel" aria-label="Permalink to “uploadModel()”">​</a></h3><blockquote><p><strong>uploadModel</strong>(<code>db3Id</code>, <code>name</code>, <code>bytes</code>, <code>upload</code>): <code>Promise</code>&lt;<a href="./Db3Index.html"><code>Db3Index</code></a>&gt;</p></blockquote><p><strong><code>Beta</code></strong></p><p>Upload an <code>ann</code> vector index&#39;s model trained elsewhere: every device holding the db3 checks it against its registration and installs it. The bytes are a model in its <code>pvm1</code> envelope, at most 64 MiB; the server stores them as they are. Devices train and upload a model on their own when none is listed, so most apps never call this. Needs read-write access through a grant, a group or the app&#39;s access. Refused <code>DB3_INDEX_MODEL_EXISTS</code> once a model is uploaded (or while a device&#39;s upload is under way), <code>DB3_INDEX_GENERATION_STALE</code> and <code>DB3_INDEX_MODEL_STALE</code> when the index moved on since <code>upload</code> names were listed, <code>DB3_INDEX_MODEL_TOO_LARGE</code> past 64 MiB.</p><h4 id="parameters-9" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-9" aria-label="Permalink to “Parameters”">​</a></h4><h5 id="db3id-9" tabindex="-1">db3Id <a class="header-anchor" href="#db3id-9" aria-label="Permalink to “db3Id”">​</a></h5><p><code>string</code></p><p>The db3.</p><h5 id="name-5" tabindex="-1">name <a class="header-anchor" href="#name-5" aria-label="Permalink to “name”">​</a></h5><p><code>string</code></p><p>The vector index&#39;s name, as <code>list</code> answers it.</p><h5 id="bytes" tabindex="-1">bytes <a class="header-anchor" href="#bytes" aria-label="Permalink to “bytes”">​</a></h5><p><code>Uint8Array</code></p><p>The model in its <code>pvm1</code> envelope.</p><h5 id="upload" tabindex="-1">upload <a class="header-anchor" href="#upload" aria-label="Permalink to “upload”">​</a></h5><p><a href="./Db3IndexModelUpload.html"><code>Db3IndexModelUpload</code></a></p><p>The index&#39;s generation and revision as <code>list</code> answers them, and how the model was trained.</p><h4 id="returns-9" tabindex="-1">Returns <a class="header-anchor" href="#returns-9" aria-label="Permalink to “Returns”">​</a></h4><p><code>Promise</code>&lt;<a href="./Db3Index.html"><code>Db3Index</code></a>&gt;</p><p>The index as it now is, listing its <code>annModel</code>.</p>',162)])])}const b=a(t,[["render",n]]);export{k as __pageData,b as default};
